  typeOf: (item: T) => string,
): Map<string, number> => {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    const type = typeOf(item);
    countsByType.set(type, (countsByType.get(type) ?? 0) + 1);
  }
  return countsByType;
};

